mapper.select:
SELECT * FROM ums_user_role
WHERE end_time IS NOT NULL AND end_time <= #{now}
ORDER BY end_time ASC, id ASC LIMIT #{limit} OFFSET #{offset}

SELECT * FROM ums_user_role
WHERE end_time IS NOT NULL AND end_time <= #{horizon}
ORDER BY end_time ASC, id ASC LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT ur.user_id FROM ums_user_role ur
INNER JOIN ums_user_login_device d ON d.user_id = ur.user_id AND d.is_current = 1 AND d.deleted = 0
WHERE ur.role_id = #{roleId}
ORDER BY ur.user_id ASC LIMIT #{limit} OFFSET #{offset}
